import{_ as a,o as t,a as i,b as l}from"./app.DKoEZOcr.js";const s="/ascendc.github.io/pr/5487/assets/mat_prog_flow.i53NBJhw.png",p="/ascendc.github.io/pr/5487/assets/nd2nz_new_3.Bn3mE3ZA.png",o="/ascendc.github.io/pr/5487/assets/zh-cn_image_0000002533171617.Da6rIv-S.png",_=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"算子实现","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/operator_impl"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/operator_impl.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/operator_impl.md","outlineHeaders":[{"level":2,"title":"实现流程","slug":"实现流程","link":"#实现流程"},{"level":2,"title":"设置Shape信息","slug":"设置Shape信息","link":"#设置Shape信息"},{"level":2,"title":"设置format格式","slug":"设置format格式","link":"#设置format格式"}],"lastUpdated":1787624724000}'),n={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/operator_impl.md"};function c(h,e,d,r,g,v){return t(),i("div",null,[...e[0]||(e[0]=[l('<div><article class="markdown-body"><h1>算子实现<span id="ZH-CN_TOPIC_0000002500548094"></span></h1><h2 id="实现流程">实现流程<span id="zh-cn_topic_0000001622514006_section6935163720564"></span><a class="header-anchor" href="#实现流程">​</a></h2><p>上文介绍了Matmul矩阵乘的数据切分方案和数据流。Ascend C提供一组Matmul高阶API，封装了这些常用的切分和数据搬运、计算的算法逻辑，方便用户快速实现Matmul矩阵乘法的运算操作。开发者在host侧通过调用API自动获取Tiling参数，该参数传递到kernel侧后，在初始化操作时传入，通过几个简单的API即可完成矩阵乘操作。完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/02_matrix/matmul_advanced_api">LINK</a>。</p><p><strong>图1</strong> 矩阵编程流程示意图<span id="zh-cn_topic_0000001622514006_fig264116391245"></span><br><img src="'+s+`" alt title="矩阵编程流程示意图"></p><p>host侧自动获取Tiling参数的关键步骤介绍如下： <span id="zh-cn_topic_0000001622514006_li19113114819525"></span></p><ol><li><p><strong>创建Tiling对象</strong>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
matmul_tiling::MultiCoreMatmulTiling tilingApi(*ascendcPlatform);
</code></pre></div><p>传入硬件平台信息创建PlatformAscendC对象，然后创建Tiling对象，硬件平台信息可以通过GetPlatformInfo获取。</p></li><li><p><strong>设置参与Matmul运算的核数，A、B的内存逻辑位置、格式和数据类型。</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>tilingApi.SetDim(ascendcPlatform-&gt;GetCoreNumAic());  
tilingApi.SetAType(AscendC::TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16, false);
tilingApi.SetBType(AscendC::TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16, false);
tilingApi.SetCType(AscendC::TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
</code></pre></div></li><li><p><strong>设置矩阵shape信息。</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>tilingApi.SetOrgShape(M, N, K); // 设置原始完整的形状M、N、K
tilingApi.SetShape(M, N, K);
</code></pre></div></li><li><p><strong>设置可用空间大小信息。</strong></p><p>设置Matmul计算时可用的L1 Buffer/L0C Buffer/Unified Buffer（UB）空间大小，-1表示AI处理器对应Buffer的大小。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>tilingApi.SetBufferSpace(-1, -1, -1);
</code></pre></div></li><li><p><strong>获取Tiling参数。</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>int64_t res = tilingApi.GetTiling(tilingData);
if (res == -1) {
    std::cout &lt;&lt; &quot;gen tiling failed&quot; &lt;&lt; std::endl;
}
</code></pre></div></li><li><p>Tiling参数的序列化保存等其他操作。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>uint32_t tcubeTilingSize = tilingData.GetDataSize();
tilingData.SaveToBuffer(tilingBuf, tcubeTilingSize);
</code></pre></div></li></ol><p><span id="zh-cn_topic_0000001622514006_li1032116474330"></span> kernel侧使用Matmul API矩阵乘运算的具体步骤如下：</p><ol><li><p><strong>创建Matmul对象。</strong></p><p>创建Matmul对象的示例如下：</p><ul><li>纯Cube模式（只有矩阵计算）场景下，建议在代码中定义ASCENDC_CUBE_ONLY宏，避免额外的性能开销。本节内容以纯Cube模式举例。</li><li>默认为MIX模式（包含矩阵计算和矢量计算），该场景下通常不定义ASCENDC_CUBE_ONLY宏，如果在程序中使用了ASCENDC_CUBE_ONLY宏，则必须使用ASCEND_IS_AIC宏和ASCEND_IS_AIV宏将Cube计算和Vector计算隔离开，更多内容请参考<a href="../fusion_operator_programming/fusion_operator_programming.html">融合算子编程</a>。</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType; 
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType; 
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType; 
AscendC::Matmul&lt;aType, bType, cType&gt; mm;
</code></pre></div><p>创建对象时需要传入A、B、C的参数类型信息，类型信息通过MatmulType来定义，包括：内存逻辑位置、数据格式、数据类型。</p></li><li><p><strong>初始化操作。</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling); // 初始化
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 Matmul高阶API内部实现时需要使用系统workspace（即对应本步骤中的GetSysWorkSpacePtr接口），开发者需要自行申请系统workspace的空间：</p><ul><li>在host侧Tiling实现时，设置总的workspace的数值大小（包含用户workspace和系统workspace），workspace空间由框架来申请并管理。系统workspace的空间大小通过<a href="../../../../api/Utils-API/platform_info/PlatformAscendC/GetLibApiWorkSpaceSize.html">GetLibApiWorkSpaceSize</a>获取。</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>size_t userWorkspaceSize = 0;
size_t systemWorkspaceSize = static_cast&lt;size_t&gt;(ascendcPlatform.GetLibApiWorkSpaceSize());
size_t workspaceSize = userWorkspaceSize + systemWorkspaceSize;
</code></pre></div></div></li><li><p><strong>设置原始矩阵shape以及当前核使用的左矩阵A、右矩阵B。</strong></p><p>多核场景下，需要根据数据切分方向为每个核设置对应的矩阵起始地址。本样例中沿M轴切分A矩阵和C矩阵：每个核读取A矩阵中<code>singleCoreM</code>行数据，B矩阵不切分，由所有核共同读取完整B矩阵。<code>SetOrgShape</code>需要在<code>SetTensorA</code>、<code>SetTensorB</code>之前调用。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mm.SetOrgShape(tiling.M, tiling.N, tiling.Ka, tiling.Kb);
mm.SetTensorA(aGlobal[GetBlockIdx() * tiling.singleCoreM * tiling.Ka], false);
mm.SetTensorB(bGlobal[0], false);
</code></pre></div><p>其中，<code>GetBlockIdx()</code>表示当前核号。A矩阵按<code>[M, Ka]</code>连续存放，因此当前核的A矩阵起始偏移为<code>GetBlockIdx() * tiling.singleCoreM * tiling.Ka</code>。各核计算C矩阵的不同行，但都需要完整的B矩阵参与K轴累加，因此B矩阵从<code>bGlobal[0]</code>开始读取。<code>SetTensorA</code>和<code>SetTensorB</code>的第二个参数<code>false</code>表示矩阵不转置。</p></li><li><p><strong>完成矩阵乘操作。</strong></p><ul><li><p>调用Iterate完成单次迭代计算，叠加while循环完成当前核负责的数据计算。C矩阵按<code>[M, N]</code>连续存放，当前核的写回起始偏移为<code>GetBlockIdx() * tiling.singleCoreM * tiling.N</code>。Iterate方式可以自行控制迭代次数，使用方式比较灵活。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>while (mm.Iterate()) {
    mm.GetTensorC(cGlobal[GetBlockIdx() * tiling.singleCoreM * tiling.N]);
}
</code></pre></div></li><li><p>调用IterateAll完成当前核负责的全部数据计算并写回C矩阵。IterateAll方式无需循环迭代，使用比较简单。本节样例代码中调用IterateAll实现矩阵乘。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mm.IterateAll(cGlobal[GetBlockIdx() * tiling.singleCoreM * tiling.N]);
</code></pre></div></li></ul></li><li><p><strong>结束矩阵乘操作。</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mm.End();
</code></pre></div></li></ol><h2 id="设置Shape信息">设置Shape信息<span id="zh-cn_topic_0000001622514006_section736714343331"></span><a class="header-anchor" href="#设置Shape信息">​</a></h2><p>在实现Host Tiling时可以设置Shape信息，用于Tiling计算；kernel侧运行时也可以修改部分Shape信息，用于尾块设置、Matmul复用（多个Matmul计算复用一个Matmul对象）等场景。本节对涉及到的Shape概念进行介绍，并给出host侧和kernel侧设置Tiling信息的指导。</p><ul><li>orgShape：M、N、K</li><li>singleCoreShape：singleCoreM、singleCoreN、singleCoreK</li><li>singleShape：singleM、singleN、singleK</li><li>baseShape：baseM、baseN、baseK</li></ul><p>通过<a href="basics.html#zh-cn_topic_0000001622194138_section68451031218">数据分块（Tiling）</a>的介绍我们已经了解了orgShape(M、N、K)，singleCoreShape(singleCoreM、singleCoreN、singleCoreK)，baseShape(baseM、baseN、baseK)的概念，如下图所示：</p><p><img src="`+p+'" alt></p><p>除此之外，单核的Matmul Tiling时，实际参与Matmul计算的shape可以是原始shape中的一部分，singleM, singleN, singleK用于表达实际参与Matmul计算的shape，如下图所示。在单核的情况下，singleM, singleN, singleK会透传给singleCoreM, singleCoreN, singleCoreK。</p><p><img src="'+o+`" alt></p><ul><li><p>核函数（Kernel）运行时设置</p><ul><li><a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetTail.html">SetTail</a>、<a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetSingleShape.html">SetSingleShape</a>都是运行时修改singleCoreM、singleCoreN、singleCoreK，处理尾块时使用<a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetTail.html">SetTail</a>，Matmul复用（多个Matmul计算复用一个Matmul对象）的场景可以使用SetSingleShape重新设置。</li><li><a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetOrgShape.html">SetOrgShape</a>是运行时修改M、N、K，Matmul复用的场景可以使用SetOrgShape重新设置。</li></ul></li><li><p>单核Tiling时设置</p><ul><li><a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetOrgShape.html">SetOrgShape</a>（必选）：设置M、N、K</li><li><a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetShape.html">SetShape</a>（非必选）：设置singleM、singleN、singleK，等同于设置singleCoreM、singleCoreN、singleCoreK</li><li><a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetFixSplit.html">SetFixSplit</a>（非必选）：设置baseM、baseN、baseK</li></ul></li><li><p>多核Tiling时设置</p><ul><li><p><a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetOrgShape.html">SetOrgShape</a>（必选）：设置M、N、K</p></li><li><p><a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetShape.html">SetShape</a>（非必选）：设置singleM、singleN、singleK</p></li><li><p><a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetFixSplit.html">SetFixSplit</a>（非必选）：设置baseM、baseN、baseK</p></li><li><p><a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetSingleShape.html">SetSingleShape</a>(非必选)：设置singleCoreM、singleCoreN、singleCoreK</p></li><li><p><a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetSingleRange.html">SetSingleRange</a>(非必选)：设置singleCoreM、singleCoreN、singleCoreK的范围</p></li></ul></li></ul><h2 id="设置format格式">设置format格式<span id="zh-cn_topic_0000001622514006_section1558462120502"></span><a class="header-anchor" href="#设置format格式">​</a></h2><p>创建Matmul对象时需要传入A、B、C的参数类型信息，类型信息通过MatmulType来定义，包括：内存逻辑位置、数据格式、数据类型。示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType; 
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType; 
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType; 
AscendC::Matmul&lt;aType, bType, cType&gt; mm;
</code></pre></div><p>针对数据格式，包括CubeFormat::ND, CubeFormat::NZ, CubeFormat::ND_ALIGN三种，ND和NZ格式在<a href="basics.html#zh-cn_topic_0000001622194138_section1453415011">数据格式</a>章节已经介绍，ND_ALIGN格式的介绍请参考<a href="../../../technical_appendix/concepts_and_terms/neural_networks_and_operators/data_layout.html#li075920427155">数据排布格式</a>。</p></article></div>`,1)])])}const u=a(n,[["render",c]]);export{_ as __pageData,u as default};
